package cn.lili.modules.community.p0.stage45;
import cn.lili.modules.community.p0.support.*;import com.google.gson.*;import org.junit.jupiter.api.Test;import java.util.*;import static cn.lili.modules.community.p0.support.Stage1Json.*;import static org.junit.jupiter.api.Assertions.*;
class Stage45ShareDetailsTest {
 JsonObject request(){return object(map("amountCent",500,"receivers",List.of(map("account","A","amountCent",300),map("account","B","amountCent",200))));}
 JsonObject receipt(String a,String b,String provider,long total){return object(map("providerState",provider,"succeededCent",total,"receivers",List.of(map("detailId","detail-a","account","A","amountCent",300,"state",a),map("detailId","detail-b","account","B","amountCent",200,"state",b))));}
 @Test void totalFinishedDoesNotTurnClosedReceiverIntoSuccess(){var value=Stage45ShareDetails.require(request(),receipt("SUCCESS","CLOSED","FINISHED",300));assertEquals(300,value.succeededCent());assertTrue(value.settled());assertFalse(value.allSuccessful());assertThrows(Stage1Exception.class,()->Stage45ShareDetails.require(request(),receipt("SUCCESS","CLOSED","FINISHED",500)));}
 @Test void finishedWithPendingDetailStillRequiresOriginalQuery(){var value=Stage45ShareDetails.require(request(),receipt("SUCCESS","PENDING","FINISHED",300));assertFalse(value.settled());assertFalse(value.allSuccessful());}
 @Test void allMatchingReceiverSuccessIsRequired(){var value=Stage45ShareDetails.require(request(),receipt("SUCCESS","SUCCESS","FINISHED",500));assertEquals(500,value.succeededCent());assertTrue(value.settled());assertTrue(value.allSuccessful());assertFalse(Stage45ShareDetails.require(request(),receipt("SUCCESS","SUCCESS","PROCESSING",500)).allSuccessful());}
 @Test void missingDuplicateOrWrongReceiverAndAmountsCannotBeAccepted(){for(int i=0;i<4;i++){var result=receipt("SUCCESS","CLOSED","FINISHED",300);var second=result.getAsJsonArray("receivers").get(1).getAsJsonObject();if(i==0)result.getAsJsonArray("receivers").remove(1);if(i==1)second.addProperty("detailId","detail-a");if(i==2)second.addProperty("account","other");if(i==3)second.addProperty("amountCent",199);assertThrows(Stage1Exception.class,()->Stage45ShareDetails.require(request(),result));}}
 @Test void laterObservationCannotEraseOrAlterSuccessfulDetails(){var before=receipt("SUCCESS","PENDING","PROCESSING",300);assertTrue(Stage45ShareDetails.monotonic(before,receipt("SUCCESS","SUCCESS","FINISHED",500)));assertFalse(Stage45ShareDetails.monotonic(before,receipt("PENDING","PENDING","PROCESSING",0)));var changed=receipt("SUCCESS","PENDING","PROCESSING",300);changed.getAsJsonArray("receivers").get(0).getAsJsonObject().addProperty("amountCent",299);assertFalse(Stage45ShareDetails.monotonic(before,changed));}
}
